import os
"""Load the generated bytes in an offline context; never use an HTTP server.
Managed Chromium blocks file://. One intercepted document response supplies the
same HTML bytes a file open would supply; all other requests are failures.
"""
from pathlib import Path
from playwright.sync_api import sync_playwright,expect,Error
import json
ROOT=Path(__file__).resolve().parent.parent
html=(ROOT/'dist/Hellscape-offline.html').read_text()
ART=ROOT/'artifacts';ART.mkdir(exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),args=['--no-sandbox'])
 checks=[]
 for width,height in [(1440,900),(390,844),(844,390)]:
  context=browser.new_context(viewport={'width':width,'height':height},offline=True,reduced_motion='reduce')
  context.add_init_script('Math.random=()=>0.25')
  errors=[];requests=[]
  context.on('page',lambda page:page.on('pageerror',lambda e:errors.append(str(e))))
  def route(r):
   if r.request.url=='http://offline.test/preview':r.fulfill(content_type='text/html',body=html)
   else:requests.append(r.request.url);r.abort()
  page=context.new_page()
  # The fully embedded document is transferred through CDP when file:// is blocked.
  # Allow that transfer on constrained CI workers, independent of network latency.
  page.set_default_navigation_timeout(120000)
  page.set_default_timeout(60000)
  try:
   page.goto((ROOT/'dist/Hellscape-offline.html').as_uri())
   file_check='opened directly from file with network disabled'
   context.on('request',lambda r:requests.append(r.url) if r.url.startswith(('http:','https:')) else None)
  except Error as error:
   if 'ERR_BLOCKED_BY_ADMINISTRATOR' not in str(error):raise
   file_check='file:// blocked by managed Chromium URL policy; exact bytes supplied by local request interception'
   context.route('**/*',route);page.goto('http://offline.test/preview')
  def frame():return page.frames[1]
  expect(frame().get_by_role('link',name='Nuova partita',exact=True)).to_be_visible()
  frame().locator('.home-illustration').evaluate('img=>img.decode()')
  frame().locator('.home-wordmark').evaluate('img=>img.decode()')
  frame().evaluate('document.fonts.ready')
  page.screenshot(path=str(ART/f'home-offline-{width}x{height}.png'))
  # Seed a site save; the export must leave it untouched and offer no resume.
  page.evaluate('localStorage.setItem("fool-v1","site-save-sentinel")')
  for bank in ['termologia','introduzione-fisica-misura']:
   frame().get_by_role('link',name='Nuova partita',exact=True).click()
   expect(frame().locator('#bank-choice')).to_be_visible();frame().locator('#bank-choice').select_option(bank)
   frame().get_by_role('button',name='Inizia partita').click()
   expect(frame().locator('.hell-race canvas')).to_have_count(1)
   frame().get_by_role('button',name='Svela e avvia il tempo').click()
   frame().locator('.answer').nth(frame().evaluate('HellscapeUI.game.s.current.correct')).click()
   expect(frame().get_by_role('button',name='Prossima domanda')).to_be_visible()
   assert frame().evaluate('HellscapeUI.game.s.valid')==1
   frame().evaluate('HellscapeUI.showRules()')
   expect(frame().locator('.rules-content .rules-page')).to_have_count(1)
   assert frame().locator('#rules-section option').count()==22
   frame().get_by_role('button',name='Torna alla partita').click()
   frame().evaluate('document.fonts.ready');page.wait_for_timeout(250)
   if bank=='termologia':page.screenshot(path=str(ART/f'offline-{width}x{height}.png'))
   frame().evaluate('HellscapeUI.goHome()');frame().get_by_role('button',name='Salva ed esci').click()
   expect(frame().get_by_role('link',name='Riprendi partita',exact=True)).to_be_visible()
   frame().get_by_role('link',name='Riprendi partita',exact=True).click()
   expect(frame().locator('.hell-race canvas')).to_have_count(1)
   assert frame().evaluate('HellscapeUI.game.s.valid')==1
   assert frame().evaluate('!HellscapeUI.game.running')
   frame().evaluate('HellscapeUI.goHome()');frame().get_by_role('button',name='Salva ed esci').click()
  assert page.evaluate('localStorage.getItem("fool-v1")')=='site-save-sentinel'
  assert not errors,errors
  assert not requests,requests
  checks.append({'viewport':[width,height],'banks':2,'errors':errors,'external_requests':requests})
  context.close()
 browser.close()
 print(json.dumps({'offline':checks,'file_url_check':file_check},indent=2))
